import json, re, urllib.parse, urllib.request

UA = "FindAParkPOC/1.0 (educational take-home; local park scaffold)"

def api(params):
    qs = urllib.parse.urlencode(params)
    url = "https://commons.wikimedia.org/w/api.php?" + qs
    req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept": "application/json"})
    with urllib.request.urlopen(req, timeout=90) as resp:
        return json.load(resp)

def strip_html(s):
    if s is None:
        return ""
    s = re.sub(r"<[^>]+>", "", str(s))
    for a, b in (("&amp;", "&"), ("&quot;", '"'), ("&#039;", "'"), ("&lt;", "<"), ("&gt;", ">"), ("&nbsp;", " ")):
        s = s.replace(a, b)
    return re.sub(r"\s+", " ", s).strip()

def meta_value(meta, key):
    raw = meta.get(key) if isinstance(meta, dict) else None
    if isinstance(raw, dict):
        return strip_html(raw.get("value"))
    if raw is None:
        return ""
    return strip_html(raw)

def canonical_thumb(thumburl):
    if not thumburl:
        return None
    parts = urllib.parse.urlsplit(thumburl)
    return "https://upload.wikimedia.org" + parts.path

def summarize(page):
    infos = page.get("imageinfo")
    info = infos[0] if isinstance(infos, list) and infos and isinstance(infos[0], dict) else {}
    meta = info.get("extmetadata") if isinstance(info.get("extmetadata"), dict) else {}
    thumb = canonical_thumb(info.get("thumburl"))
    return {
        "title": page.get("title"),
        "missing": "missing" in page,
        "mime": info.get("mime"),
        "width": info.get("width"),
        "height": info.get("height"),
        "thumbwidth": info.get("thumbwidth"),
        "user": info.get("user"),
        "thumb": thumb,
        "artist": meta_value(meta, "Artist"),
        "license": meta_value(meta, "LicenseShortName"),
        "usage": meta_value(meta, "UsageTerms"),
        "licenseUrl": meta_value(meta, "LicenseUrl"),
    }

def file_info(title):
    data = api({
        "action": "query",
        "format": "json",
        "prop": "imageinfo",
        "iiprop": "url|user|size|mime|extmetadata",
        "iiurlwidth": "1280",
        "titles": title,
    })
    pages = list(((data.get("query") or {}).get("pages") or {}).values())
    if not pages:
        return {"title": title, "missing": True}
    return summarize(pages[0])

files = [
    "File:Prospect_Park_New_York_October_2015_003.jpg",
    "File:Riverside_Park_02.jpg",
    "File:Riverside_Park_Pier_I.jpg",
    "File:Bryant_Park_jeh.JPG",
    "File:Brooklyn_Botanic_Garden_New_York_May_2015_panorama_2.jpg",
    "File:Bluebells_in_the_Brooklyn_Botanic_Garden_(42915p).jpg",
    "File:Salt_Marsh_in_Gerritsen_Beach_(10813p).jpg",
    "File:Brooklyn_Banks-_the_skatepark_that_wasn't_supposed_to_be_a_skatepark_(4264784146).jpg",
    "File:Flushing_Meadows_Meadow_Lake_td_(2018-05-26)_25_-_Baseball_Field_13.jpg",
    "File:Playground_2947.jpg",
]
known = [file_info(t) for t in files]
print("KNOWN")
for row in known:
    print(json.dumps(row, ensure_ascii=False))

queries = {
    "cedar-hill-nature-preserve": "deciduous forest boardwalk trail",
    "east-ridge-trailhead": "ridge trail overlook New York",
    "lakeshore-point": "fishing pier waterfront park",
}
search = {}
for key, q in queries.items():
    data = api({
        "action": "query",
        "format": "json",
        "generator": "search",
        "gsrsearch": q + " filetype:bitmap",
        "gsrnamespace": "6",
        "gsrlimit": "10",
        "prop": "imageinfo",
        "iiprop": "url|mime|size",
        "iiurlwidth": "1280",
    })
    rows = []
    for page in ((data.get("query") or {}).get("pages") or {}).values():
        s = summarize(page)
        if s.get("thumb") and s.get("width") and s["width"] >= 1280 and s.get("mime", "").startswith("image/") and "1280px-" in s["thumb"]:
            full = file_info(s["title"])
            rows.append(full)
    search[key] = rows
    print("\nSEARCH", key, len(rows))
    for s in rows:
        print(json.dumps({k: s.get(k) for k in ("title","mime","width","thumbwidth","license","usage","artist","thumb")}, ensure_ascii=False))

with open("/Users/nicknavarro/Learn/find-parks-poc/tmp/commons-search.json", "w") as f:
    json.dump({"known": known, "search": search}, f, indent=2, ensure_ascii=False)
print("WROTE")
